/**
 * **Static concept refs** — authoring against names, not instances.
 *
 * The IR already references every action and query by name; these refs bring
 * the fluent authoring layer up to the same discipline. A vocabulary binds
 * each concept *name* to its canonical class and returns per-concept ref
 * objects whose members represent actions and queries as data:
 *
 * ```ts
 * export const { Posting, Conversing } = vocabulary({
 *   concepts: { Posting: PostingConcept, Conversing: ConversingConcept },
 * }).concepts;
 *
 * when(Posting.create, { content }, { post })        // a reaction against names
 * Posting._getPost({ post }).is({ author })          // a read against names
 * ```
 *
 * A ref resolves to the live instrumented member when the reaction, view, or
 * former registers with an engine — the same name→instance resolution the
 * IR import path uses. Until then it is inert data; calling one directly
 * throws an error that names the unresolved reference.
 *
 * Naming is a design choice: the vocabulary key is the concept's name in the
 * log, the rendered spec, and the wire. Two names may share one class (two
 * instances of one behavior), and a build may substitute any structurally
 * conforming implementation for a name (for example, a persistent version) —
 * the vocabulary's class stays the canonical, type-defining one.
 */
import type { QueryReadLine, SlotPattern } from "../../reads/lines.ts";
import type { ExactPattern } from "../../reads/type-inference.ts";
import type { CheckedComputationFns, ComputationFn, ComputationRef } from "../../reads/computations.ts";
import { type ConceptMetadata } from "../concepts/concept-metadata.ts";
import type { ActionCall, InstrumentedAction, Reaction, IsListForm, QueryAsAsked, TriggerActionLine } from "../types.ts";
import type { QueryPromise } from "../../reads/query-metadata.ts";
export { isActionRef, isQueryRef } from "./references.ts";
export type { ActionRef, QueryRef } from "./references.ts";
declare const VocabularyClasses: unique symbol;
declare const VocabularyComputations: unique symbol;
declare const VocabularyMetadata: unique symbol;
declare const ActionTypeAnchor: unique symbol;
/** Any concept class the vocabulary can hold. */
export type ConceptClass = new (...args: never[]) => object;
/** The row shape a query's declared answer carries. */
type QueryRow<A> = Awaited<A> extends readonly (infer Row)[] ? Row : Awaited<A>;
/**
 * The line builder a query member becomes on its vocabulary ref: called with
 * a pattern over the query's own inputs, it answers a line typed by the
 * query's row — `.is` slots check against the row's fields. The second
 * overload is a type anchor only — `ReturnType` (how the generated wire
 * names a query's answer) resolves to the class's own declared answer; every
 * actual call matches the first overload and answers a line.
 */
type ExactSlotPattern<Shape, Pattern> = ExactPattern<Shape, Pattern>;
type QueryLineFn<F> = F extends (input: infer I) => infer A ? {
    <const Pattern extends SlotPattern<I>>(pattern: ExactSlotPattern<I, Pattern>): QueryReadLine<QueryRow<A>>;
    (input: I): A;
} : F;
/**
 * An action member called as authored data instead of executed directly. The
 * final, uncallable overload anchors generated `ReturnType` and `Parameters`
 * references to the declared implementation signature; authored calls select
 * the generic line-builder overload so input completeness remains visible.
 */
type RequiredInputKeys<I> = {
    [K in keyof I]-?: [I[K]] extends [never] ? never : {} extends Pick<I, K> ? never : K;
}[keyof I];
type ActionLineFn<F> = F extends (input: infer I) => infer A ? {
    <P extends SlotPattern<I>>(pattern: P): RequiredInputKeys<I> extends keyof P ? ActionCall<F & InstrumentedAction, P, A> : TriggerActionLine<F & InstrumentedAction, P, A>;
    (input: I, anchor: typeof ActionTypeAnchor): A;
} : F;
/**
 * The members of a concept instance as its vocabulary ref exposes them:
 * actions become callable data lines for `when` and `then`;
 * queries become typed line builders — the callable vocabulary proxy.
 */
type ConceptRef<Entry extends ConceptEntry, I = InstanceType<ClassOf<Entry>>> = {
    readonly [K in keyof I as I[K] extends (...args: never[]) => unknown ? K : never]: K extends `_${string}` ? QueryLineFn<K extends BatchedNames<Entry> ? QueryAsAsked<I[K]> : I[K]> : ActionLineFn<I[K]>;
};
/**
 * The type of an entry's `batched` value, `undefined` where it has none. The
 * runtime reads `batched` only from a declaration, never from a class.
 */
type BatchedValue<Entry> = Entry extends ConceptClass ? undefined : Entry extends unknown ? "batched" extends keyof Entry ? Entry["batched" & keyof Entry] : undefined : never;
/**
 * The queries a concept entry names under `batched`. The types follow `batched`
 * only when its type names one list of queries for every value it admits; see
 * `BatchedProblem`. Any other entry is refused where it is written.
 */
type BatchedNames<Entry> = [BatchedProblem<BatchedValue<Entry>>] extends [never] ? NamesIn<Exclude<BatchedValue<Entry>, undefined>> : never;
type NamesIn<List> = List extends readonly unknown[] ? List[number] : never;
type IsUnion<T, U = T> = T extends unknown ? ([U] extends [T] ? false : true) : false;
type ElementProblem<List extends readonly unknown[], Seen = never> = List extends readonly [
    infer Head,
    ...infer Tail
] ? 0 extends 1 & Head ? "names a query by a value typed any" : string extends Head ? "names a query by a string, not a literal name" : IsUnion<Head> extends true ? "names one query or another" : [Head] extends [Seen] ? "names a query twice" : ElementProblem<Tail, Seen | Head> : never;
/**
 * Why the types cannot tell which queries a `batched` value names, or never
 * when they can. They can when the value is surely present or surely absent,
 * is one list rather than one of several, has a fixed length, and names each
 * query once by one literal name. For any other value, the runtime would batch
 * names the types do not follow, or none they do, and a call that compiles
 * would answer wrongly.
 */
export type BatchedProblem<List> = 0 extends 1 & List ? "is typed any" : [List] extends [undefined] ? never : undefined extends List ? [NamesIn<Exclude<List, undefined>>] extends [never] ? never : "may be left out" : IsUnion<List> extends true ? "is one of several lists" : List extends readonly unknown[] ? number extends List["length"] ? "is not a fixed list of names" : IsUnion<List["length"]> extends true ? "has a name that may be left out" : ElementProblem<List> : "is not a list";
/**
 * The names under `batched` that are not queries of the class taking a list of
 * inputs. The runtime refuses a name that is not a query, and calls a query
 * that takes one input with a list, so it would answer wrongly.
 */
export type SingleFormBatched<C extends ConceptClass, Names> = Names extends string ? Names extends Extract<keyof InstanceType<C>, `_${string}`> ? IsListForm<InstanceType<C>[Names]> extends true ? never : Names : Names : never;
/** The compile error for a batched name that is not a query taking a list of inputs. */
export type SingleFormRefusal<Name> = Name extends string ? `batched names ${Name}, which is not a query taking a list of inputs: give the query one parameter typed Input[] and return one answer per input.` : never;
/**
 * The compile error for a `batched` value the types cannot follow. A value typed
 * `any` would satisfy any message, so it meets `never` instead.
 */
export type BatchedRefusal<Problem extends string> = Problem extends "is typed any" ? never : `batched ${Problem}, so the types cannot tell which queries it batches: write the query names inline, as string literals. To stop grouping reads, set groupBatchedQueries: false.`;
/** The batched query names of each vocabulary entry. */
export type BatchedQueryNames<T extends Record<string, ConceptEntry>> = {
    readonly [K in keyof T]: BatchedNames<T[K]>;
};
/** The vocabulary's refs: one `ConceptRef` per declared name. */
type VocabularyRefs<T extends Record<string, ConceptEntry>> = {
    readonly [K in keyof T]: ConceptRef<T[K]>;
};
/** A concept class plus metadata owned by its vocabulary name. */
type ConceptDeclaration<C extends ConceptClass> = ConceptMetadata & {
    readonly class: C;
    readonly spec?: string;
};
export type ConceptEntry = ConceptClass | ConceptDeclaration<ConceptClass>;
type QueryKeys<I> = Extract<keyof I, `_${string}`>;
type QueryRowIsValid<T> = T extends (...args: never[]) => unknown ? false : T extends readonly unknown[] ? false : T extends object ? true : false;
type QueryAnswerIsValid<T> = Awaited<T> extends readonly (infer Row)[] ? QueryRowIsValid<Row> : QueryRowIsValid<Awaited<T>>;
type QueryAnswerMatchesPromise<Answer, Promise> = [Promise] extends [never] ? QueryAnswerIsValid<Answer> : QueryPromise extends Promise ? QueryAnswerIsValid<Answer> : [Promise] extends ["one"] ? Awaited<Answer> extends readonly unknown[] ? false : QueryRowIsValid<Awaited<Answer>> : [Promise] extends ["optional" | "many"] ? Awaited<Answer> extends readonly (infer Row)[] ? QueryRowIsValid<Row> : false : QueryAnswerIsValid<Answer>;
type DeclaredQueryPromise<Entry, Key extends PropertyKey> = Entry extends {
    readonly queries: infer Queries;
} ? Key extends keyof Queries ? Queries[Key] : never : Entry extends {
    readonly class: infer Class;
} ? Class extends {
    readonly queries: infer Queries;
} ? Key extends keyof Queries ? Queries[Key] : never : never : never;
type InvalidQueryKeys<Entry extends ConceptEntry, I = InstanceType<ClassOf<Entry>>> = {
    [K in QueryKeys<I>]: (K extends BatchedNames<Entry> ? QueryAsAsked<I[K]> : I[K]) extends (...args: never[]) => infer Answer ? QueryAnswerMatchesPromise<Answer, DeclaredQueryPromise<Entry, K>> extends true ? never : K : K;
}[QueryKeys<I>];
type CheckedConceptEntry<E extends ConceptEntry> = [BatchedProblem<BatchedValue<E>>] extends [never] ? [SingleFormBatched<ClassOf<E>, BatchedNames<E>>] extends [never] ? CheckedQueries<E> : E & {
    readonly batched: SingleFormRefusal<SingleFormBatched<ClassOf<E>, BatchedNames<E>>>;
} : E & {
    readonly batched: BatchedRefusal<BatchedProblem<BatchedValue<E>> & string>;
};
type CheckedQueries<E extends ConceptEntry> = E extends ConceptClass ? InvalidQueryKeys<E> extends never ? E : never : E extends ConceptDeclaration<infer C> ? E & {
    readonly class: InvalidQueryKeys<E> extends never ? C : never;
} : never;
type CheckedConceptEntries<T extends Record<string, ConceptEntry>> = {
    [K in keyof T]: CheckedConceptEntry<T[K]>;
};
type ClassOf<E extends ConceptEntry> = E extends ConceptDeclaration<infer C> ? C : E extends ConceptClass ? E : never;
export type ConceptClassesOf<T extends Record<string, ConceptEntry>> = {
    readonly [K in keyof T]: ClassOf<T[K]>;
};
type ComputationRefs<T extends Record<string, ComputationFn>> = {
    readonly [K in keyof T]: ComputationRef<T[K]>;
};
/** Concept and computation refs grouped by their role. */
export interface DeclaredVocabulary<TConcepts extends Record<string, ConceptEntry>, TComputations extends Record<string, ComputationFn>> {
    readonly concepts: VocabularyRefs<TConcepts>;
    readonly computations: ComputationRefs<TComputations>;
    readonly [VocabularyClasses]: ConceptClassesOf<TConcepts>;
    readonly [VocabularyComputations]: ComputationRefs<TComputations>;
    readonly [VocabularyMetadata]: Record<string, ConceptMetadata>;
}
interface VocabularyDeclaration<TConcepts extends Record<string, ConceptEntry>, TComputations extends Record<string, ComputationFn>> {
    concepts: TConcepts;
    computations?: TComputations;
}
/**
 * Declare the application's concept vocabulary: each name bound to its
 * canonical class. Returns the refs used to author reactions. Assembly also
 * uses the declaration to construct default concept instances.
 */
export declare function vocabulary<const TConcepts extends Record<string, ConceptEntry>, const TComputations extends Record<string, ComputationFn>>(declaration: VocabularyDeclaration<TConcepts, TComputations> & {
    concepts: CheckedConceptEntries<TConcepts>;
    computations?: CheckedComputationFns<TComputations>;
}): DeclaredVocabulary<TConcepts, TComputations>;
/** The class map a vocabulary was declared with (how `assemble` constructs). */
export declare function vocabularyClasses(vocab: DeclaredVocabulary<Record<string, ConceptEntry>, Record<string, ComputationFn>>): Record<string, ConceptClass>;
/** The vocabulary-scoped computations an assembly installs. */
export declare function vocabularyComputations(vocab: object): Record<string, ComputationRef>;
/** Metadata associated with each vocabulary concept name. */
export declare function vocabularyMetadata(vocab: object): Record<string, ConceptMetadata>;
/**
 * Tag a reaction so an assembly can discover it in composition exports.
 * Views and formers carry their own tags, as do endpoint declarations that
 * specialize the reaction frame; untagged helpers remain ordinary exports.
 * The wrapper also lets the callback's destructured parameter infer as
 * {@link Vars}, so reactions need no type annotation.
 */
export declare function reaction(reaction: Reaction): Reaction;
export declare function isReaction(value: unknown): value is Reaction;
